// Shared by the live editor, reproducible texture exporter and book preview.
export const STORAGE='selected-work-layout-v1';
export const groups=['background','back','front','lower','title'];
const cache=new Map();
export async function loadImage(src){if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>{cache.delete(src);reject(Error('无法加载图片：'+src.slice(0,120)))};i.src=src}));return cache.get(src)}
export async function assets(){return Object.fromEntries(await Promise.all(['background','frame','wood','binder','sage','tape','title'].map(async n=>[n,await loadImage('/selected-work/assets/'+n+'.png')])))}
export function cordY(group,x){const t=x/1659;return group==='back'?38+440*t-478*t*t:group==='front'?532+145*t-500*t*t:398+510*t-320*t*t}
export function makeCanvas(w=1659,h=948){const c=document.createElement('canvas');c.width=w;c.height=h;return c}
function rope(ctx,group){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();for(let x=-20;x<=1680;x+=4){const y=cordY(group,x);if(x===-20)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle='#b68651';ctx.lineWidth=10;ctx.shadowColor='#80592b35';ctx.shadowBlur=3;ctx.shadowOffsetY=2;ctx.stroke();ctx.shadowColor='transparent';ctx.strokeStyle='#e5be83';ctx.lineWidth=6;ctx.stroke();for(let x=-20;x<=1680;x+=6){const y=cordY(group,x);ctx.beginPath();ctx.moveTo(x-2,y-3);ctx.lineTo(x+2,y+3);ctx.lineWidth=1.5;ctx.strokeStyle=x%12===0?'#a77843':'#f2d6a5';ctx.stroke()}ctx.restore()}
function photo(ctx,img,x,y,w,h,fit){const s=fit==='cover'?Math.max(w/img.width,h/img.height):Math.min(w/img.width,h/img.height);ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(img,x+(w-img.width*s)/2,y+(h-img.height*s)/2,img.width*s,img.height*s);ctx.restore()}
// Nine-slice the reusable paper, retaining natural border thickness instead of stretching it.
export function portraitSize(height,ratio=9/19.5){return {height,width:(height-78)*ratio+18}}
export function upgradePortrait(config){
 if(config.frameStyle==='polaroid-portrait')return config;
 if(config.frameStyle==='portrait'){config.cards=config.cards.map(c=>({...c,...portraitSize(c.height)}));config.frameStyle='polaroid-portrait';return config;}
 config.cards=config.cards.map(c=>{const y=cordY(c.cord,c.x),top=c.clip==='sage'&&c.cord==='lower'?60:18;
  const height=Math.min(320,Math.floor((930-y-top-25)/Math.cos(c.angle*Math.PI/180)));
  return {...c,...portraitSize(Math.max(200,height)),fit:'contain'};
 });config.frameStyle='polaroid-portrait';return config;
}
function paper(ctx,img,x,y,w,h){
 const sx=[0,img.width*.075,img.width*.925,img.width],sy=[0,img.height*.072,img.height*.776,img.height];
 const dx=[x,x+9,x+w-9,x+w],dy=[y,y+26,y+h-52,y+h];
 for(let j=0;j<3;j++)for(let i=0;i<3;i++)ctx.drawImage(img,sx[i],sy[j],sx[i+1]-sx[i],sy[j+1]-sy[j],dx[i],dy[j],dx[i+1]-dx[i],dy[j+1]-dy[j]);
}
function card(ctx,c,a,photos,selected){
 const y=cordY(c.cord,c.x),w=c.width,h=c.height;
 const top=c.clip==='sage'&&c.cord==='lower'?60:18;
 ctx.save();ctx.translate(c.x,y);ctx.rotate(c.angle*Math.PI/180);
 ctx.shadowColor='#39332735';ctx.shadowBlur=5;ctx.shadowOffsetX=3;ctx.shadowOffsetY=5;
 paper(ctx,a.frame,-w/2,top,w,h);ctx.shadowColor='transparent';
 if(photos[c.id])photo(ctx,photos[c.id],-w/2+9,top+26,w-18,h-78,c.fit);
 if(selected===c.id){ctx.strokeStyle='#7158a4';ctx.lineWidth=2;ctx.setLineDash([7,5]);ctx.strokeRect(-w/2-4,top-4,w+8,h+8)}
 const hardware=c.clip;
 const cw=hardware==='sage'?110:hardware==='binder'?72:hardware==='tape'?w*.6:28;
 const ch=hardware==='sage'?92:hardware==='binder'?95:hardware==='tape'?43:103;
 const clipTop=hardware==='tape'?-8:hardware==='sage'&&c.cord==='lower'?-14:-ch*.52;
 ctx.shadowColor='#49382425';ctx.shadowBlur=2;ctx.shadowOffsetY=2;
 ctx.drawImage(a[hardware],-cw/2,clipTop,cw,ch);
 if(hardware==='sage'&&c.cord==='lower'){
  // Small metal suspension loop passes over the rope and through the handle eye.
  ctx.shadowColor='transparent';ctx.lineWidth=3;ctx.strokeStyle='#72766a';
  ctx.beginPath();ctx.ellipse(0,-1,5,9,0,0,Math.PI*2);ctx.stroke();
  ctx.lineWidth=1;ctx.strokeStyle='#eeeedd';ctx.beginPath();ctx.ellipse(-.6,-1.4,4,8,0,Math.PI,Math.PI*2);ctx.stroke();
 }
 ctx.restore();
}
export async function renderLayers(config,a,{selected=null,hidePhotos=false,hideCards=false}={}){const photos={};if(!hidePhotos)await Promise.all(config.cards.filter(c=>c.image).map(async c=>photos[c.id]=await loadImage(c.image)));config={...config,cards:config.cards.map(c=>photos[c.id]?{...c,...portraitSize(c.height,Math.min(.65,Math.max(.35,photos[c.id].width/photos[c.id].height)))}:c)};return groups.map(group=>{const canvas=makeCanvas(config.width,config.height),ctx=canvas.getContext('2d');if(group==='background')ctx.drawImage(a.background,0,0,canvas.width,canvas.height);else if(group==='title'){ctx.globalAlpha=config.title.opacity;if(config.title.text==='Selected Work')ctx.drawImage(a.title,config.title.x,config.title.y,config.title.width,config.title.height);else {ctx.fillStyle='#74685e';ctx.font='italic 180px cursive';ctx.fillText(config.title.text,70,450,1450)}
 if(!hideCards){ctx.globalAlpha=1;ctx.globalCompositeOperation='destination-out';
  for(const c of config.cards){const hw=c.clip,w=c.width,cw=hw==='sage'?110:hw==='binder'?72:hw==='tape'?w*.6:28,ch=hw==='sage'?92:hw==='binder'?95:hw==='tape'?43:103,top=hw==='tape'?-8:hw==='sage'&&c.cord==='lower'?-14:-ch*.52;
   ctx.save();ctx.translate(c.x,cordY(c.cord,c.x));ctx.rotate(c.angle*Math.PI/180);ctx.drawImage(a[hw],-cw/2,top,cw,ch);ctx.restore();}
  ctx.globalCompositeOperation='source-over';}
 }else{rope(ctx,group);if(!hideCards)config.cards.filter(c=>c.cord===group).forEach(c=>card(ctx,c,a,photos,selected))}return {group,canvas}})}
export function composite(layers){const c=makeCanvas();for(const l of layers)c.getContext('2d').drawImage(l.canvas,0,0);return c}
export function validateConfig(c){if(c?.width!==1659||c?.height!==948||!Array.isArray(c.cards)||c.cards.length!==13)throw Error('请导入本页面导出的 13 相框配置');if(!c.title||typeof c.title.text!=='string'||!Number.isFinite(c.title.opacity)||c.title.opacity<0||c.title.opacity>1)throw Error('标题配置无效');const ids=new Set();for(const p of c.cards){if(ids.has(p.id)||typeof p.id!=='string'||!['back','front','lower'].includes(p.cord)||!['wood','sage','binder','tape'].includes(p.clip)||!['contain','cover'].includes(p.fit)||!['x','width','height','angle'].every(k=>Number.isFinite(p[k]))||p.width<40||p.width>500||p.height<40||p.height>600||p.x<0||p.x>1659||Math.abs(p.angle)>45|| (p.image&&!/^data:image\/(png|jpeg|webp);base64,/.test(p.image)))throw Error('相框配置无效');ids.add(p.id)}for(const k of ['x','y','width','height'])if(!Number.isFinite(c.title[k]))throw Error('标题位置无效');return upgradePortrait(c)}
