import {assets,renderLayers,composite,STORAGE,validateConfig} from './selected-work-render.js';
const $=id=>document.getElementById(id), defaults=validateConfig(await (await fetch('/selected-work/layout.json')).json());
let config=structuredClone(defaults),hidden=false,revision=0;
try {const saved=localStorage.getItem(STORAGE);if(saved)config=validateConfig(JSON.parse(saved))}catch{ $('status').textContent='本机配置无法读取，已载入默认布局。'}
const a=await assets();
config.cards.forEach(c=>{const opt=document.createElement('option');opt.value=c.id;opt.textContent=c.name;$('card').append(opt)});
const current=()=>config.cards.find(c=>c.id===$('card').value);
function controls(){const c=current();$('x').value=c.x;$('angle').value=c.angle;$('fit').value=c.fit;$('title').value=config.title.text;$('opacity').value=config.title.opacity}
async function draw(){const n=++revision;try{const layers=await renderLayers(config,a,{hidePhotos:hidden});if(n!==revision)return;const ctx=$('preview').getContext('2d');ctx.clearRect(0,0,1659,948);ctx.drawImage(composite(layers),0,0)}catch(e){$('status').textContent=e.message}}
function download(name,data,type){const link=document.createElement('a');link.download=name;const url=URL.createObjectURL(new Blob([data],{type}));link.href=url;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('card').onchange=controls;
for(const name of ['x','angle','fit'])$(name).oninput=()=>{current()[name]=name==='fit'?$(name).value:Number($(name).value);draw()};
$('title').oninput=()=>{config.title.text=$('title').value;draw()};$('opacity').oninput=()=>{config.title.opacity=Number($('opacity').value);draw()};
$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 PNG、JPEG 或 WebP 图片');const bitmap=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();current().image=c.toDataURL('image/png');hidden=false;await draw();$('status').textContent='图片已替换。点击“保存到本机书页”应用。'}catch(e){$('status').textContent=e.message}};
$('remove').onclick=()=>{current().image=null;$('file').value='';draw()};$('empty').onclick=()=>{hidden=!hidden;$('empty').textContent=hidden?'显示全部图片':'暂时隐藏全部图片';draw()};
$('save').onclick=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(config));$('status').textContent='已保存。重新打开书本，第二跨页会载入这份布局。'}catch{$('status').textContent='浏览器空间不足，请导出配置备份，或缩小图片后重试。'}};
$('export').onclick=()=>download('selected-work-layout.json',JSON.stringify(config,null,2),'application/json');
$('png').onclick=async()=>{const c=composite(await renderLayers(config,a,{hidePhotos:hidden}));c.toBlob(b=>download('selected-work.png',b,'image/png'))};
$('import').onchange=async()=>{try{config=validateConfig(JSON.parse(await $('import').files[0].text()));controls();await draw();$('status').textContent='配置已导入，保存后应用到书页。'}catch(e){$('status').textContent=e.message}};
$('reset').onclick=()=>{config=structuredClone(defaults);hidden=false;controls();draw();$('status').textContent='已恢复默认，保存后应用到书页。'};
window.selectedWork={get config(){return config},assets:a,renderLayers,composite,draw,setConfig(c){config=validateConfig(c);controls();return draw()}};
controls();await draw();$('status').textContent='独立素材已加载；共 13 个可替换相框。';
